"""One-time source edit to add compact discovery controls to the existing surf page."""
from pathlib import Path
root=Path(__file__).resolve().parents[2]
p=root/'internal/admin/static/index.html';text=p.read_text(encoding='utf8')
needle='<div class="surf-target-picker">'
block='''<details class="surf-discovery-settings"><summary>内容发现与去重</summary>
<div class="field-grid">
<div><label for="surf-cooldown-days">同主题分享冷却（天）</label><input id="surf-cooldown-days" type="number" min="1" max="90"></div>
<div><label for="surf-source-budget">每轮最多读取来源数</label><input id="surf-source-budget" type="number" min="1" max="4"></div>
<div><label for="surf-depth">关联探索最多层数</label><input id="surf-depth" type="number" min="0" max="3"></div>
</div><p class="hint">先从内容源发现候选，再由角色决定深入、收藏或分享。音乐、视频、图片仍遵守各自发送权限；每轮工具总预算沿用联网设置。</p>
<div id="surf-discovery-weights" class="surf-weight-grid"></div><p class="hint">权重会自动归一化，不必合计100；不可全部为0。来源不可用时降低优先级，保留具体失败原因。</p>
<fieldset id="surf-builtin-sources"><legend>内容源</legend></fieldset>
<label for="surf-rss-sources">追加RSS／Atom订阅（每行：名称 | 网址 | 文字／音乐／视频／图片）</label><textarea id="surf-rss-sources" rows="3" placeholder="我的订阅 | https://example.com/feed | 文字"></textarea>
<p class="hint">可填写RSSHub或Miniflux提供的公开订阅地址。受限、需登录或只有网页壳的来源不会被当成有效正文。</p></details>'''
assert text.count(needle)==1 and 'id="surf-cooldown-days"'not in text
text=text.replace(needle,block+needle)
needle='<article class="panel surf-controls">'
history='''<details class="panel surf-history-panel" id="surf-history-panel"><summary>浏览轨迹与收藏</summary><div class="inline-actions"><span id="surf-history-state" class="hint" role="status">展开后读取；不会自动移动阅读位置。</span><button id="surf-history-refresh" class="secondary" type="button">刷新浏览记录</button></div><div id="surf-history-list"></div></details>'''
assert text.count(needle)==1;text=text.replace(needle,history+needle);p.write_text(text,encoding='utf8')
p=root/'internal/admin/static/surf.js';text=p.read_text(encoding='utf8')
text=text.replace("web_search:'搜索网页'","web_discover:'发现多源内容',web_search:'搜索网页'").replace("surf_started:'开始自主冲浪'","surf_source:'读取内容源',surf_started:'开始自主冲浪'")
text=text.replace("state.settings=s;renderTargets()","state.settings=s;fillDiscovery(s.discovery);renderTargets()")
text=text.replace("max_sessions_per_day:Number($('#surf-budget').value),topics,threads}","max_sessions_per_day:Number($('#surf-budget').value),topics,threads,discovery:readDiscovery()}")
needle=" $('#surf-save').addEventListener('click',save);"
assert text.count(needle)==1
code=''' const weightNames={recommendations:'推荐流',community:'社区热门',subscriptions:'订阅更新',related:'关联漫游',search:'搜索核实'};
 const formatNames={text:'文字',voice:'音乐',video:'视频',image:'图片'};
 let discoveryConfig=null,historyBusy=false;
 function fillDiscovery(d){if(!d)return;discoveryConfig=structuredClone(d);$('#surf-cooldown-days').value=d.cooldown_days;$('#surf-source-budget').value=d.max_sources;$('#surf-depth').value=d.max_depth;const weights=$('#surf-discovery-weights');weights.replaceChildren();for(const [key,title]of Object.entries(weightNames)){const wrap=node(weights,'div'),label=node(wrap,'label',title),input=node(wrap,'input');input.id='surf-weight-'+key;input.type='number';input.min='0';input.max='100';input.value=d.weights[key]||0;label.htmlFor=input.id;input.addEventListener('input',dirty)}const box=$('#surf-builtin-sources');box.replaceChildren();node(box,'legend','内容源');for(const source of d.sources.filter(x=>!x.id.startsWith('custom-'))){const label=node(box,'label',undefined,'surf-source-choice'),check=node(label,'input');check.type='checkbox';check.checked=source.enabled;check.dataset.source=source.id;node(label,'span',source.name+' · '+(formatNames[source.kind]||source.kind));check.addEventListener('change',dirty)}$('#surf-rss-sources').value=d.sources.filter(x=>x.id.startsWith('custom-')).map(x=>x.name+' | '+x.url+' | '+formatNames[x.kind]).join('\\n')}
 function readDiscovery(){if(!discoveryConfig)throw new Error('内容发现设置尚未读取，请刷新后重试');const d=structuredClone(discoveryConfig);for(const [id,key,min,max]of [['surf-cooldown-days','cooldown_days',1,90],['surf-source-budget','max_sources',1,4],['surf-depth','max_depth',0,3]]){const value=Number($('#'+id).value);if(!Number.isInteger(value)||value<min||value>max)throw new Error('请检查冷却天数、来源数与关联探索层数');d[key]=value}d.weights={};for(const key of Object.keys(weightNames)){const value=Number($('#surf-weight-'+key).value);if(!Number.isInteger(value)||value<0||value>100)throw new Error('发现方式权重须为0–100整数');d.weights[key]=value}if(!Object.values(d.weights).some(x=>x>0))throw new Error('至少一种发现方式的权重应大于0');d.sources=d.sources.filter(x=>!x.id.startsWith('custom-')).map(x=>({...x,enabled:$('#surf-builtin-sources input[data-source="'+x.id+'"]').checked}));const formats={文字:'text',音乐:'voice',视频:'video',图片:'image'};for(const [i,line]of $('#surf-rss-sources').value.split(/\\r?\\n/).map(x=>x.trim()).filter(Boolean).entries()){const [name,url,kind]=line.split('|').map(x=>x.trim());let u;try{u=new URL(url)}catch{}if(!name||!u||!['http:','https:'].includes(u.protocol)||u.username||u.password||!formats[kind])throw new Error('订阅格式应为：名称 | 公开网址 | 文字／音乐／视频／图片');d.sources.push({id:'custom-'+i,name,url,type:'rss',kind:formats[kind],enabled:true})}if(d.sources.length>12||!d.sources.some(x=>x.enabled))throw new Error('最多12个内容源，至少启用一个');return d}
 const historyStates={browsing:'已发现候选',prepared:'已准备，等待发送',shared:'已分享',not_shared:'仅浏览，未分享',bookmarked:'已收藏'};
 async function refreshHistory(){if(historyBusy||!window.WechatAdmin?.isAuthenticated())return;historyBusy=true;$('#surf-history-refresh').disabled=true;try{const data=await api('/api/surf/history'),box=$('#surf-history-list'),pos=box.scrollTop;box.replaceChildren();const bookmarks=(data.items||[]).filter(x=>x.bookmarked);if(bookmarks.length){node(box,'strong','收藏 · '+bookmarks.length+' 项');for(const item of bookmarks.slice(-15).reverse()){const p=node(box,'p');const a=node(p,'a',item.item.title);a.href=item.item.url;a.target='_blank';a.rel='noopener noreferrer'}}for(const session of (data.sessions||[]).slice(-20).reverse()){const row=node(box,'details',undefined,'surf-history-session');node(row,'summary',time(session.at)+' · '+(weightNames[session.mode]||session.mode)+' · '+(historyStates[session.state]||session.state)+' · '+session.candidates.length+'项');for(const item of session.candidates){const p=node(row,'p'),a=node(p,'a',item.title);a.href=item.url;a.target='_blank';a.rel='noopener noreferrer';node(p,'small',' · '+item.source+' / '+(formatNames[item.kind]||item.kind)+(session.selected===item.id?' / 本轮选择':''))}if(session.visited?.length)node(row,'p','继续读取／准备：'+session.visited.join(' · '));for(const failure of session.failures||[])node(row,'p',failure,'form-error')}if(!box.children.length)node(box,'p','尚无新机制的浏览记录。','empty');box.scrollTop=pos;$('#surf-history-state').textContent='最近20次浏览；刷新不会触发搜索或分享。'}catch(e){$('#surf-history-state').textContent='读取失败：'+e.message}finally{historyBusy=false;$('#surf-history-refresh').disabled=false}}
 $('#surf-history-refresh').addEventListener('click',refreshHistory);$('#surf-history-panel').addEventListener('toggle',()=>{if($('#surf-history-panel').open)refreshHistory()});['surf-cooldown-days','surf-source-budget','surf-depth','surf-rss-sources'].forEach(id=>$('#'+id).addEventListener('input',dirty));
'''
text=text.replace(needle,code+needle)
text=text.replace("state.settings=null;state.version++","state.settings=null;discoveryConfig=null;$('#surf-history-list').replaceChildren();state.version++")
p.write_text(text,encoding='utf8')
p=root/'internal/admin/static/app.css';text=p.read_text(encoding='utf8');text+='''
.surf-discovery-settings{margin-block:18px;padding-block:14px;border-block:1px solid var(--line)}.surf-discovery-settings summary,.surf-history-panel>summary{cursor:pointer;padding:8px 0;font-weight:600}.surf-weight-grid{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:12px;margin-top:18px}.surf-weight-grid input{width:100%;min-width:0}#surf-builtin-sources{border:0;padding:10px 0;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}#surf-builtin-sources legend{font-weight:600;padding-bottom:8px}.surf-source-choice{display:flex;align-items:center;gap:10px;min-height:44px;min-width:0}.surf-source-choice input{width:18px;flex:0 0 18px;margin:0}.surf-source-choice span{overflow-wrap:anywhere}#surf-history-list{max-height:520px;overflow:auto;overscroll-behavior:contain}.surf-history-session{padding:14px 0;border-top:1px solid var(--line);overflow-wrap:anywhere}.surf-history-session summary{cursor:pointer;line-height:1.7}.surf-history-session p{font-size:13px}.surf-history-session small{color:var(--muted)}@media(max-width:700px){.surf-weight-grid{grid-template-columns:repeat(2,minmax(0,1fr))}#surf-builtin-sources{grid-template-columns:1fr}}
''';p.write_text(text,encoding='utf8')
